<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Accessor\ThemeCustomCssAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ThemeCustomCssAccessor trait.
 *
 * Covers null default, string/VO assignment via withCustomCss,
 * getCustomCss/customCss accessors, and isCustomCssChanged with/without original.
 */
class ThemeCustomCssAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withCustomCss creates a new instance with the CustomCss set
     * from a string value, and getCustomCss returns the primitive string.
     */
    public function testWithCustomCssFromString(): void
    {
        // Arrange
        $holder = new ImplWithThemeCustomCssAccessorUnitTest();

        // Act
        $result = $holder->withCustomCss('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getCustomCss());
    }
    /**
     * Asserts that withcustomCss has access to the value object
     * from a string value, and getCustomCss returns the primitive string.
     */
    public function testWithCustomCssFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithThemeCustomCssAccessorUnitTest();

        // Act
        $result = $holder->withCustomCss('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->customCss()->value());
    }
    public function testChangedCustomCss(): void
    {
        // Arrange
        $holder = new ImplWithThemeCustomCssAccessorUnitTest();
        $original = $holder->withCustomCss( 'one');
        $same = $holder->withCustomCss( 'one');
        $modified = $holder->withCustomCss('other');

        // Act
        $unchanged = $holder->isCustomCssChanged();
        $withSame = $original->isCustomCssChanged( $same );
        $withDiferent = $original->isCustomCssChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithThemeCustomCssAccessorUnitTest
{
  use ThemeCustomCssAccessor;
}
